-- Retail 1.4.83: ONE existing-database metadata upgrade; PREPARATION ONLY.
-- Do not apply until this exact file and the actual server/database are approved.
-- Close Retail safely and obtain the required backup before operator application.
-- Select the existing Retail database in SSMS. No USE/CREATE DATABASE is run.
-- No business backfill, stock adjustment, queue/checkpoint reset or activation.
IF @@TRANCOUNT<>0 BEGIN RAISERROR('Run this update outside an existing transaction.',16,1); RETURN; END;
-- Beta-only target. Production needs its separately reviewed package.
IF DB_NAME() COLLATE Latin1_General_100_BIN2<>N'POS_Local_Beta' OR DATALENGTH(DB_NAME())<>DATALENGTH(N'POS_Local_Beta')
  THROW 51031,'Select the exact isolated beta database; no update was applied.',1;
IF OBJECT_ID(N'dbo.pos_schema_migrations',N'U') IS NOT NULL
  EXEC sys.sp_executesql N'IF EXISTS(SELECT 1 FROM dbo.pos_schema_migrations WHERE version>24) THROW 51031,''A newer core schema requires a new reviewed package.'',1;';

SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON; SET CONCAT_NULL_YIELDS_NULL ON; SET NUMERIC_ROUNDABORT OFF; SET XACT_ABORT ON;
SET NOCOUNT ON;
BEGIN TRY
 BEGIN TRANSACTION;
IF DB_NAME() IN (N'master',N'model',N'msdb',N'tempdb')
  THROW 51003, 'Select the configured Retail POS database before applying this update.', 1;
IF EXISTS (SELECT 1 FROM sys.tables WHERE is_ms_shipped=0)
   AND OBJECT_ID(N'dbo.pos_schema_migrations',N'U') IS NULL
  THROW 51003, 'This is not an empty or managed Retail POS database. No tables were changed.', 1;
 IF OBJECT_ID(N'dbo.pos_schema_migrations',N'U') IS NULL THROW 51028,'An existing managed Retail database is required.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.pos_schema_migrations WHERE version=24) THROW 51028,'Reviewed Retail core schema 24 is required; no update was applied.',1;
 DECLARE @metadataLock int;
 EXEC @metadataLock=sys.sp_getapplock @Resource=N'RetailExistingMetadataUpgrade',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=3000;
 IF @metadataLock<0 THROW 51028,'Another database update is running; no update was applied.',1;
 -- Validate the existing core before any new metadata is created.
 EXEC sys.sp_executesql N'DECLARE @expectedColumns TABLE(table_name nvarchar(128) NOT NULL,name nvarchar(128) NOT NULL,collation nvarchar(128) NULL,PRIMARY KEY(table_name,name));
