,{"table_name":"terminal_tokens","name":"platform","collation":"$DATABASE_DEFAULT"},{"table_name":"terminal_tokens","name":"reissued_at","collation":null},{"table_name":"terminal_tokens","name":"replaced_by","collation":null},{"table_name":"terminal_tokens","name":"revoked_at","collation":null},{"table_name":"terminal_tokens","name":"row_version","collation":null},{"table_name":"terminal_tokens","name":"status","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"allow_decimal","collation":null},{"table_name":"uom_units","name":"code","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"created_at","collation":null},{"table_name":"uom_units","name":"deleted_at","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"id","collation":null},{"table_name":"uom_units","name":"is_active","collation":null},{"table_name":"uom_units","name":"name","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"row_version","collation":null},{"table_name":"uom_units","name":"sort","collation":null},{"table_name":"uom_units","name":"updated_at","collation":null},{"table_name":"user_roles","name":"created_at","collation":null},{"table_name":"user_roles","name":"id","collation":null},{"table_name":"user_roles","name":"role","collation":"$DATABASE_DEFAULT"},{"table_name":"user_roles","name":"user_id","collation":null},{"table_name":"whatsapp_queue","name":"body","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"created_at","collation":null},{"table_name":"whatsapp_queue","name":"error","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"id","collation":null},{"table_name":"whatsapp_queue","name":"phone_number_id","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"queued_at","collation":null},{"table_name":"whatsapp_queue","name":"recipient","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"reference","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"sent_at","collation":null},{"table_name":"whatsapp_queue","name":"status","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"store_id","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"updated_at","collation":null}]'') WITH(table_name nvarchar(128) ''$.table_name'',name nvarchar(128) ''$.name'',collation nvarchar(128) ''$.collation'');
 DECLARE @definitionVariants TABLE(category varchar(24),table_name nvarchar(128),name nvarchar(128),field varchar(32),canonical nvarchar(max),lf_hash binary(32),windows_hash binary(32),PRIMARY KEY(category,table_name,name,field));
 INSERT @definitionVariants SELECT category,table_name,name,field,canonical,CONVERT(binary(32),lf_hash,2),CONVERT(binary(32),windows_hash,2) FROM OPENJSON(N''[{"category":"triggers","table_name":"bookings","name":"TR_bookings_set_kind","field":"definition","canonical":"\n    CREATE   TRIGGER dbo.TR_bookings_set_kind\n    ON dbo.bookings\n    AFTER INSERT, UPDATE\n    AS\n    BEGIN\n      SET NOCOUNT ON;\n      UPDATE booking\n         SET booking_kind = N''''racket''''\n        FROM dbo.bookings booking\n        JOIN inserted incoming ON incoming.id = booking.id\n       WHERE COALESCE(booking.booking_kind, N''''standard'''') <> N''''racket''''\n         AND (\n           NULLIF(LTRIM(RTRIM(COALESCE(incoming.racket_model, N''''''''))), N'''''''') IS NOT NULL\n           OR NULLIF(LTRIM(RTRIM(COALESCE(incoming.string_type, N''''''''))), N'''''''') IS NOT NULL\n           OR incoming.tension_main IS NOT NULL OR incoming.tension_cross IS NOT NULL\n           OR incoming.dropped_off_at IS NOT NULL OR incoming.promised_at IS NOT NULL\n           OR incoming.job_status_by IS NOT NULL OR incoming.job_status_at IS NOT NULL\n           OR NULLIF(LTRIM(RTRIM(COALESCE(incoming.tag_id, N''''''''))), N'''''''') IS NOT NULL\n           OR NULLIF(LTRIM(RTRIM(COALESCE(incoming.string_origin, N''''''''))), N'''''''') IS NOT NULL\n           OR incoming.string_source_product_id IS NOT NULL OR incoming.grip_product_id IS NOT NULL\n           OR NULLIF(LTRIM(RTRIM(COALESCE(incoming.technician, N''''''''))), N'''''''') IS NOT NULL\n         );\n    END;","lf_hash":"025f9a026afb71eaf7ba570714733d332752b152a075deb2e33562d54eb03b8e","windows_hash":"a1e3414a9c455079a05e07ae58b7775b2357885e2ab4b0f3366d8b6bf8b51dc6"},{"category":"triggers","table_name":"held_orders","name":"held_orders_lifecycle","field":"definition","canonical":"CREATE   TRIGGER dbo.held_orders_lifecycle ON dbo.held_orders\nAFTER INSERT, UPDATE AS\nBEGIN\n SET NOCOUNT ON;\n IF TRIGGER_NESTLEVEL(OBJECT_ID(N''''dbo.held_orders_lifecycle''''))>1 RETURN;\n IF EXISTS(SELECT 1 FROM inserted i WHERE i.status=''''completed''''\n AND NOT EXISTS(SELECT 1 FROM dbo.sales s WHERE s.store_id=i.store_id AND s.bill_number=i.bill_no)\n AND NOT EXISTS(SELECT 1 FROM dbo.bookings b WHERE i.note=N''''booking:''''+CONVERT(nvarchar(36),b.id) AND b.store_id=i.store_id AND b.shift_id=i.shift_id))\n THROW 51023,''''Only a saved sale or matching booking may finish a draft bill.'''',1;\n -- Keep terminal states from old rows, and recognize sales synced before drafts.\n UPDATE h SET status=CASE WHEN d.status IN (''''completed'''',''''cancelled'''') THEN d.status ELSE ''''completed'''' END,\n row_version=COALESCE(h.row_version,0)+1,updated_at=SYSDATETIMEOFFSET()\n FROM dbo.held_orders h JOIN inserted i ON i.id=h.id LEFT JOIN deleted d ON d.id=i.id\n WHERE (d.status IN (''''completed'''',''''cancelled'''') AND h.status<>d.status)\n OR (h.status NOT IN (''''completed'''',''''cancelled'''') AND EXISTS(SELECT 1 FROM dbo.sales s WHERE s.store_id=h.store_id AND s.bill_number=h.bill_no));\n IF EXISTS(SELECT 1 FROM dbo.held_orders h JOIN inserted i ON i.id=h.id\n LEFT JOIN dbo.shifts s WITH (UPDLOCK,HOLDLOCK) ON CONVERT(nvarchar(36),s.id)=h.shift_id AND s.store_id=h.store_id\n WHERE h.status NOT IN (''''completed'''',''''cancelled'''') AND h.shift_id IS NOT NULL AND (s.id IS NULL OR s.state<>N''''ACTIVE''''))\n THROW 51020,''''This shift is closing or closed. The draft cannot be changed.'''',1;\nEND;","lf_hash":"dc690d0a8f2bc11e80fe5013d022702c5bc1c007eca2dc27d58ed4574efd2ee7","windows_hash":"7fe6a24215bde2084111ddc3e30c452284fd3ba1da6d07756e0c3fb44c68c655"},{"category":"triggers","table_name":"pos_settings","name":"pos_settings_zero_stock_catalog_backfill","field":"definition","canonical":"CREATE   TRIGGER dbo.pos_settings_zero_stock_catalog_backfill ON dbo.pos_settings\nAFTER INSERT, UPDATE AS\nBEGIN\n SET NOCOUNT ON;\n IF NOT UPDATE(integration_settings) RETURN;\n IF COALESCE((SELECT LOWER(COALESCE(JSON_VALUE(CASE WHEN ISJSON(integration_settings)=1 THEN integration_settings ELSE N''''{}'''' END,''''$.autoArchiveZeroStock''''),N''''true'''')) FROM inserted WHERE id=1),N''''false'''')<>N''''true'''' RETURN;\n IF EXISTS (SELECT 1 FROM deleted WHERE id=1 AND LOWER(COALESCE(JSON_VALUE(CASE WHEN ISJSON(integration_settings)=1 THEN integration_settings ELSE N''''{}'''' END,''''$.autoArchiveZeroStock''''),N''''true''''))=N''''true'''') RETURN;\n UPDATE p\nSET is_archived=CASE WHEN s.quantity>0 THEN 0 ELSE 1 END,\n    archived_at=CASE WHEN s.quantity>0 THEN NULL ELSE COALESCE(p.archived_at,SYSDATETIMEOFFSET()) END,\n    updated_at=SYSDATETIMEOFFSET(), row_version=COALESCE(p.row_version,0)+1\nFROM dbo.products p\n\nCROSS APPLY (SELECT COALESCE(SUM(TRY_CONVERT(decimal(38,12),j.[value])),0) AS quantity\n FROM OPENJSON(CASE WHEN ISJSON(p.stock_by_store)=1 AND LEFT(LTRIM(p.stock_by_store),1)=N''''{'''' THEN p.stock_by_store ELSE N''''{}'''' END) j) s\nWHERE p.deleted_at IS NULL AND ISJSON(p.stock_by_store)=1 AND LEFT(LTRIM(p.stock_by_store),1)=N''''{''''\n AND (p.is_archived<>CASE WHEN s.quantity>0 THEN 0 ELSE 1 END\n      OR (s.quantity>0 AND p.archived_at IS NOT NULL));\nEND;","lf_hash":"8b7ce84d425ae60d5d67d4ee9af0b54e37bc16fce334ec1839fea635ceaeb950","windows_hash":"a9aa15c14852ca8d79afd6a02b2025adcbabe5f1984b4bb425f2cd7c68678632"},{"category":"triggers","table_name":"products","name":"products_zero_stock_catalog_lifecycle","field":"definition","canonical":"CREATE   TRIGGER dbo.products_zero_stock_catalog_lifecycle ON dbo.products\nAFTER INSERT, UPDATE AS\nBEGIN\n SET NOCOUNT ON;\n IF TRIGGER_NESTLEVEL(OBJECT_ID(N''''dbo.products_zero_stock_catalog_lifecycle''''))>1 RETURN;\n IF NOT (UPDATE(stock_by_store) OR UPDATE(is_archived)) RETURN;\n IF COALESCE((SELECT LOWER(COALESCE(JSON_VALUE(CASE WHEN ISJSON(integration_settings)=1 THEN integration_settings ELSE N''''{}'''' END,''''$.autoArchiveZeroStock''''),N''''true'''')) FROM dbo.pos_settings WHERE id=1),N''''true'''')<>N''''true'''' RETURN;\n UPDATE p\nSET is_archived=CASE WHEN s.quantity>0 THEN 0 ELSE 1 END,\n    archived_at=CASE WHEN s.quantity>0 THEN NULL ELSE COALESCE(p.archived_at,SYSDATETIMEOFFSET()) END,\n    updated_at=SYSDATETIMEOFFSET(), row_version=COALESCE(p.row_version,0)+1\nFROM dbo.products p\nJOIN inserted i ON i.id=p.id\nCROSS APPLY (SELECT COALESCE(SUM(TRY_CONVERT(decimal(38,12),j.[value])),0) AS quantity\n FROM OPENJSON(CASE WHEN ISJSON(p.stock_by_store)=1 AND LEFT(LTRIM(p.stock_by_store),1)=N''''{'''' THEN p.stock_by_store ELSE N''''{}'''' END) j) s\nWHERE p.deleted_at IS NULL AND ISJSON(p.stock_by_store)=1 AND LEFT(LTRIM(p.stock_by_store),1)=N''''{''''\n AND (p.is_archived<>CASE WHEN s.quantity>0 THEN 0 ELSE 1 END\n      OR (s.quantity>0 AND p.archived_at IS NOT NULL));\nEND;","lf_hash":"dd9fef63159e341267e355e3194855d324f129d8de5a89b27c4a1cf306bcc048","windows_hash":"dde85b830a05bf27d20b8fcdebd5732e3a27e09b5d79dfbdf53d47a6255a360a"},{"category":"triggers","table_name":"sales","name":"sales_complete_held_ticket","field":"definition","canonical":"CREATE   TRIGGER dbo.sales_complete_held_ticket ON dbo.sales\nAFTER INSERT AS\nBEGIN\n SET NOCOUNT ON;\n IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.held_orders h ON h.store_id=i.store_id AND h.bill_no=i.bill_number WHERE h.status=''''cancelled'''')\n THROW 51021,''''This draft bill was cancelled. Start a new bill.'''',1;\n UPDATE h SET status=''''completed'''',row_version=COALESCE(h.row_version,0)+1,updated_at=SYSDATETIMEOFFSET()\n FROM dbo.held_orders h JOIN inserted i ON i.store_id=h.store_id AND i.bill_number=h.bill_no\n WHERE h.status NOT IN (''''completed'''',''''cancelled'''');\nEND;","lf_hash":"580a319d74fe1e62bc6a345e7390306f08f8f43f3b43257fa173ec5b35657c25","windows_hash":"955ed4e73704dd716dfc9218d1dcf98ffdd2b63cb91e772b64989be592e19d09"},{"category":"triggers","table_name":"shifts","name":"shifts_unfinished_tickets","field":"definition","canonical":"CREATE   TRIGGER dbo.shifts_unfinished_tickets ON dbo.shifts\nAFTER UPDATE AS\nBEG