 INSERT @definitionVariants SELECT category,table_name,name,field,canonical,CONVERT(binary(32),lf_hash,2),CONVERT(binary(32),windows_hash,2) FROM OPENJSON(N''[{"category":"triggers","table_name":"pos_shift_recovery_evidence","name":"TR_pos_shift_recovery_evidence_immutable","field":"definition","canonical":"CREATE TRIGGER dbo.TR_pos_shift_recovery_evidence_immutable ON dbo.pos_shift_recovery_evidence\n INSTEAD OF UPDATE, DELETE AS BEGIN SET NOCOUNT ON; THROW 50000, ''''Recovery evidence is append-only.'''', 1; END;","lf_hash":"3705f90c932cba021dda4ef79234a08b61e2decc2b10b0572ef9b1bc65bd9940","windows_hash":"cae01a906ef6784efb36675ec255d717e565fe49159435ae7b498b2ec5f56321"}]'') WITH(category varchar(24),table_name nvarchar(128),name nvarchar(128),field varchar(32),canonical nvarchar(max),lf_hash varchar(64),windows_hash varchar(64));
