IF @fingerprint IS NULL OR @fingerprint<>N''FE69AAC7EBF3F545C0B40BCDC441E4EEAA48AFAC5D70417E5930E30B94EA87D4'' THROW 51028,N''Unrecognized 028_retained_shift_evidence objects; the entire update was rolled back.'',1;
SET @fingerprint=CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CASE WHEN EXISTS(SELECT 1 FROM (SELECT t.name table_name,c.name,SCHEMA_NAME(ty.schema_id) type_schema,ty.name type_name,c.max_length,c.precision,c.scale,CONVERT(int,c.is_nullable) nullable,CONVERT(int,c.is_identity) [identity],CONVERT(int,c.is_computed) computed,
      CASE WHEN e.collation=N''$DATABASE_DEFAULT'' AND c.collation_name=CONVERT(sysname,DATABASEPROPERTYEX(DB_NAME(),''Collation'')) THEN N''$DATABASE_DEFAULT'' ELSE c.collation_name END collation,
      CASE WHEN dc.is_system_named=1 THEN N''$SYSTEM_NAMED'' ELSE dc.name END default_name,dc.definition default_definition,cc.definition computed_definition,CONVERT(int,cc.is_persisted) persisted,
      CONVERT(int,c.is_ansi_padded) ansi_padded,CONVERT(int,c.is_rowguidcol) rowguid,CONVERT(int,c.is_sparse) sparse,CONVERT(int,c.is_column_set) column_set,CONVERT(int,c.is_filestream) filestream,CONVERT(int,c.is_hidden) hidden,c.generated_always_type generated,
