      CASE WHEN e.collation=N''$DATABASE_DEFAULT'' AND c.collation_name=CONVERT(sysname,DATABASEPROPERTYEX(DB_NAME(),''Collation'')) THEN N''$DATABASE_DEFAULT'' ELSE c.collation_name END collation,
      CASE WHEN dc.is_system_named=1 THEN N''$SYSTEM_NAMED'' ELSE dc.name END default_name,dc.definition default_definition,cc.definition computed_definition,CONVERT(int,cc.is_persisted) persisted,
      CONVERT(int,c.is_ansi_padded) ansi_padded,CONVERT(int,c.is_rowguidcol) rowguid,CONVERT(int,c.is_sparse) sparse,CONVERT(int,c.is_column_set) column_set,CONVERT(int,c.is_filestream) filestream,CONVERT(int,c.is_hidden) hidden,c.generated_always_type generated,
      CONVERT(nvarchar(100),ic.seed_value) identity_seed,CONVERT(nvarchar(100),ic.increment_value) identity_increment
      FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.default_constraints dc ON dc.object_id=c.default_object_id LEFT JOIN sys.computed_columns cc ON cc.object_id=c.object_id AND cc.column_id=c.column_id LEFT JOIN sys.identity_columns ic ON ic.object_id=c.object_id AND ic.column_id=c.column_id
      LEFT JOIN @expectedColumns e ON e.table_name=t.name AND e.name=c.name WHERE t.schema_id=SCHEMA_ID(N''dbo'') AND ((t.schema_id=SCHEMA_ID(N''dbo'') AND t.name IN(N''pos_shift_recovery_evidence'')))) current_shape OUTER APPLY(SELECT category,canonical FROM @definitionVariants v WHERE v.category=N''columns'' AND v.table_name=current_shape.table_name AND v.name=current_shape.name AND v.field=N''default_definition'' AND HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),current_shape.[default_definition])) IN(v.lf_hash,v.windows_hash)) variant0 OUTER APPLY(SELECT category,canonical FROM @definitionVariants v WHERE v.category=N''columns'' AND v.table_name=current_shape.table_name AND v.name=current_shape.name AND v.field=N''computed_definition'' AND HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),current_shape.[computed_definition])) IN(v.lf_hash,v.windows_hash)) variant1 ORDER BY CONVERT(nvarchar(max),[table_name]) COLLATE Latin1_General_100_BIN2,CONVERT(nvarchar(max),[name]) COLLATE Latin1_General_100_BIN2,CONVERT(nvarchar(max),[type_schema]) COLLATE Latin1_General_100_BIN2,CONVERT(nvarchar(max),[type_name]) COLLATE Latin1_General_100_BIN2,[max_length],[precision],[scale],[nullable],[identity],[computed],CONVERT(nvarchar(max),[collation]) COLLATE Latin1_General_100_BIN2,CONVERT(nvarchar(max),[default_name]) COLLATE Latin1_General_100_BIN2,CONVERT(nvarchar(max),[default_definition]) COLLATE Latin1_General_100_BIN2,CONVERT(nvarchar(max),[computed_definition]) COLLATE Latin1_General_100_BIN2,[persisted],[ansi_padded],[rowguid],[sparse],[column_set],[filestream],[hidden],[generated],CONVERT(nvarchar(max),[identity_seed]) COLLATE Latin1_General_100_BIN2,CONVERT(nvarchar(max),[identity_increment]) COLLATE Latin1_General_100_BIN2 FOR JSON PATH,INCLUDE_NULL_VALUES) ELSE N''[]'' END)),2);
