  ((decision_kind=''''ADMIN_ACCEPTED_CLOUD'''' AND receipt_recovery_id IS NULL AND receipt_json IS NULL) OR
   (decision_kind=''''RECEIPT_NORMALIZATION'''' AND receipt_recovery_id IS NOT NULL AND receipt_json IS NOT NULL))),
