ore_settings'' AND c.name=N''allow_branch_shift_sharing'')) nonempty_shape) THEN (SELECT CONVERT(nvarchar(max),current_shape.[table_name]) AS [table_name],CONVERT(nvarchar(max),current_shape.[name]) AS [name],CONVERT(nvarchar(max),current_shape.[type_schema]) AS [type_schema],CONVERT(nvarchar(max),current_shape.[type_name]) AS [type_name],CONVERT(int,current_shape.[max_length]) AS [max_length],CONVERT(int,current_shape.[precision]) AS [precision],CONVERT(int,current_shape.[scale]) AS [scale],CONVERT(int,current_shape.[nullable]) AS [nullable],CONVERT(int,current_shape.[identity]) AS [identity],CONVERT(int,current_shape.[computed]) AS [computed],CONVERT(nvarchar(max),current_shape.[collation]) AS [collation],CONVERT(nvarchar(max),current_shape.[default_name]) AS [default_name],CONVERT(nvarchar(max),CASE WHEN variant0.category IS NOT NULL THEN variant0.canonical ELSE current_shape.[default_definition] END) AS [default_definition],CONVERT(nvarchar(max),CASE WHEN variant1.category IS NOT NULL THEN variant1.canonical ELSE current_shape.[computed_definition] END) AS [computed_definition],CONVERT(int,current_shape.[persisted]) AS [persisted],CONVERT(int,current_shape.[ansi_padded]) AS [ansi_padded],CONVERT(int,current_shape.[rowguid]) AS [rowguid],CONVERT(int,current_shape.[sparse]) AS [sparse],CONVERT(int,current_shape.[column_set]) AS [column_set],CONVERT(int,current_shape.[filestream]) AS [filestream],CONVERT(int,current_shape.[hidden]) AS [hidden],CONVERT(int,current_shape.[generated]) AS [generated],CONVERT(nvarchar(max),current_shape.[identity_seed]) AS [identity_seed],CONVERT(nvarchar(max),current_shape.[identity_increment]) AS [identity_increment] FROM (SELECT t.name table_name,c.name,SCHEMA_NAME(ty.schema_id) type_schema,ty.name type_name,c.max_length,c.precision,c.scale,CONVERT(int,c.is_nullable) nullable,CONVERT(int,c.is_identity) [identity],CONVERT(int,c.is_computed) computed,
